import AppKit

/// The editor's document window, and the two things it decides: where a bare
/// Space goes (spec §11 K-1, kpgalligan/framejob#35), and when text gives
/// the keys back (K-4, `TextFocus` below), which it asks first.
///
/// **Space is the transport's unless the first responder is typing or claims
/// it.** The window routes a bare Space key-DOWN (⇧ and ⇪ allowed, any other
/// modifier untouched) BEFORE dispatch, because dispatch is what beeped when
/// the WINDOW was first responder — as it still can be when a focused view is
/// removed (`OptionFieldControl.finishEditing` hands focus to the content
/// view since #60): `NSWindow.keyDown` forwards to nothing, and
/// `NSResponder.noResponder(for:)` beeps — the key never reached
/// `EditorViewController.keyDown`.
///
/// Three claimants keep the key:
/// - an editable `NSTextView` — every field editor, the Text tab's area, the
///   canvas's inline editor, the Media tab's search field — so a Space is
///   TYPED there;
/// - an `NSButton` (which covers `NSPopUpButton`) or an `NSSegmentedControl`:
///   they press on Space by AppKit's own convention, reachable only under
///   Full Keyboard Access, and an accessibility user keeps it;
/// - the canvas overlay (`CanvasOverlayView`), whose own Space arms a pan and
///   toggles play on key-UP (`PreviewCanvasView.handleKeyUp`).
/// And nothing is taken while a sheet is attached. An auto-repeat of a Space
/// the window took is swallowed. A non-editable field editor (a selectable
/// label), a slider, the window itself and every custom inspector control
/// are the transport's.
///
/// `handleEditorCharacter`'s `case " "` in `EditorViewController` stays for
/// the preview panel's forward (`PreviewWindowController.keyDown`) and is
/// dead for this window.
enum SpaceKeyRoute: Equatable { case transport, held, responder }

enum SpaceKey {
    /// nil unless `event` is a key-DOWN of keyCode 49 whose device-independent
    /// flags ⊆ [.shift, .capsLock]. Pure: reads only its arguments.
    static func route(
        _ event: NSEvent, firstResponder: NSResponder?, sheetAttached: Bool
    ) -> SpaceKeyRoute? {
        guard event.type == .keyDown, event.keyCode == 49 else { return nil }
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        guard flags.subtracting([.shift, .capsLock]).isEmpty else { return nil }
        if sheetAttached { return .responder }
        if (firstResponder as? NSTextView)?.isEditable == true { return .responder }
        if firstResponder is NSButton || firstResponder is NSSegmentedControl
            || firstResponder is CanvasOverlayView
        {
            return .responder
        }
        if event.isARepeat { return .held }
        return .transport
    }
}

/// When the editor window takes the keys back from text (spec §11 K-4):
/// typing is focus-averse. Only a click, or a command that exists to type,
/// gives text the keys; a click outside it, Tab (unless Full Keyboard Access
/// is on), and Return in a one-line field hand them back to the content
/// view — the root that holds the bare-key map — BEFORE dispatch, so Space
/// plays the moment typing ends.
///
/// Before dispatch because of what dispatch did: a click on the timeline,
/// which refuses first responder, left the field editor attached, and
/// AppKit's own Return re-selected the field after its commit — both behind
/// no focus ring, so the next Space was typed into a field that looked left.
/// Each field still commits through its own end-of-editing path, as on any
/// blur. Pure, so a probe can ask it.
enum TextFocus {
    /// The text taking keys when `responder` is editable text — every field
    /// editor, the Text tab's area, the canvas's inline editor, the
    /// composer — else nil.
    static func typing(_ responder: NSResponder?) -> NSTextView? {
        guard let text = responder as? NSTextView, text.isEditable else { return nil }
        return text
    }

    /// Where a click keeps the typing: a field editor's field, or the
    /// `OptionFieldControl` that frames it (its margins and chevron are the
    /// field's own); else the text view's scroll view, so a scroller is
    /// inside; else the text view.
    static func host(of text: NSTextView) -> NSView {
        if text.isFieldEditor, let field = text.delegate as? NSView {
            return (field.superview as? OptionFieldControl) ?? field
        }
        return text.enclosingScrollView ?? text
    }

    /// True when the key-down `event` leaves `text`: Tab or ⇧Tab in any
    /// text, unless `fullKeyboardAccess` — then Tab is AppKit's key-view
    /// loop, how such a user reaches a control (K-1's exception); Return or
    /// keypad Enter in a field editor (⇧ ⇪, and the keypad and fn flags,
    /// allowed). ⌃Tab, ⌥Return and ⌘ are AppKit's; a multi-line view routes
    /// its own Return (`TextEditKey`). Never while an input method has
    /// marked text.
    static func leavesOnKey(
        _ event: NSEvent, in text: NSTextView, fullKeyboardAccess: Bool
    ) -> Bool {
        guard event.type == .keyDown, !text.hasMarkedText() else { return false }
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        switch event.keyCode {
        case 48:
            return !fullKeyboardAccess && flags.subtracting([.shift, .capsLock]).isEmpty
        case 36, 76:
            return text.isFieldEditor
                && flags.subtracting([.shift, .capsLock, .numericPad, .function]).isEmpty
        default:
            return false
        }
    }

    /// True when a mouse-down whose content hit is `hit` leaves `text`: a
    /// hit outside its host. nil — the click is outside the content view,
    /// on the title bar — never leaves.
    static func leavesOnClick(hit: NSView?, in text: NSTextView) -> Bool {
        guard let hit else { return false }
        return !hit.isDescendant(of: host(of: text))
    }
}

/// The bare-key map's modifier rule, read by `handleEditorKey` (#61).
enum EditorKey {
    /// Device-independent part of `flags` minus [.shift, .capsLock] must be empty, except that on a
    /// function-key scalar (0xF700...0xF8FF) .numericPad and .function are also allowed. ⌘ ⌥ ⌃ .help never. Pure.
    static func isBare(_ flags: NSEvent.ModifierFlags, scalar: UInt32) -> Bool {
        var allowed: NSEvent.ModifierFlags = [.shift, .capsLock]
        if (0xF700...0xF8FF).contains(scalar) { allowed.formUnion([.numericPad, .function]) }
        return flags.intersection(.deviceIndependentFlagsMask).subtracting(allowed).isEmpty
    }
}

final class EditorWindow: NSWindow {
    /// Forwards to `super` unchanged. Declared because the unavailable coder
    /// init below is a designated initializer, and declaring one stops Swift
    /// inheriting `NSWindow`'s — without it `EditorWindowController`'s
    /// construction does not typecheck.
    override init(
        contentRect: NSRect, styleMask style: NSWindow.StyleMask,
        backing backingStoreType: NSWindow.BackingStoreType, defer flag: Bool
    ) {
        for clip in snapshot.clips {
            points.insert(clip.start)
            points.insert(clip.end)
        }
        return points.sorted()
    }

    /// JKL (spec §9): L steps forward 1× → 2× → 4×, J the same backwards, K
    /// pauses. A rate the item cannot serve is AVFoundation's business.
    private static let shuttleRates: [Float] = [1, 2, 4]

    private func shuttle(forward: Bool) {
        let rate = playback.rate
        let sign: Float = forward ? 1 : -1
        let magnitude = abs(rate)
        guard rate * sign > 0 else {
            playback.setRate(sign)
            return
        }
        let next = Self.shuttleRates.first { $0 > magnitude + 0.01 } ?? magnitude
        playback.setRate(sign * next)
    override func keyDown(with event: NSEvent) {
        if handleEditorKey(event) { return }
        super.keyDown(with: event)
    }

    /// Bare keys only, and never while text is being edited — a modifier-less
    /// letter must not be stolen from the timecode field or (later) an inline
    /// text clip. Everything with a modifier arrives as a menu key
    /// equivalent instead, which is also where it gets validated.
    ///
    /// Internal rather than private since road map 2's phase 8b: the preview
    /// window is a second window, so its content view is not in this
    /// controller's responder chain and has nowhere to send a bare Space or
    /// J/K/L. It hands the event here rather than carrying a second copy of the
    /// map (`PreviewWindowController.swift`), which is the one thing that could
    /// make the two windows' transports disagree.
    func handleEditorKey(_ event: NSEvent) -> Bool {
        if view.window?.firstResponder is NSText { return false }
        // And never while a sheet is attached — the same invariant
        // `validateUserInterfaceItem` opens with below, because this map is
        // not only transport: `t` adds a text clip, `w`/`e` trim, `m` marks,
        // `,`/`.` nudge, `i`/`o` write the range. A sheet captures a project
        // handle and reads it again later, so the document must not move
        // under it. Until phase 8b that held here for free and needed no line,
        // since a sheet takes the editor window's key status and this method
        // was simply unreachable while one was up. But a sheet is WINDOW-modal
        // rather than application-modal (measured: with one attached
        // `NSApp.modalWindow` is nil, and the preview panel is visible and
        // `canBecomeKey`), and the panel forwards its bare keys straight here,
        // where no validator stands — `t` added a text clip behind an open
        // export card that had already captured the project it was about to
        // write, and Remove Silences, which computes its spans ONCE, would
        // have rippled ranges that no longer described the timeline. The guard
        // belongs beside the key map rather than in the panel: both windows
        // inherit it, no second copy can drift, and the editor's own path pays
        // nothing for a case it cannot reach.
        if view.window?.attachedSheet != nil { return false }
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        guard let scalar = event.charactersIgnoringModifiers?.unicodeScalars.first else {
            return false
        }
        guard EditorKey.isBare(flags, scalar: scalar.value) else { return false }
        let shift = flags.contains(.shift)
        switch scalar.value {
        case UInt32(NSLeftArrowFunctionKey):
            stepFrames(shift ? -10 : -1)
        case UInt32(NSRightArrowFunctionKey):
            stepFrames(shift ? 10 : 1)
        case UInt32(NSUpArrowFunctionKey):
            previousEditPoint(nil)
        case UInt32(NSDownArrowFunctionKey):
            nextEditPoint(nil)
        case UInt32(NSHomeFunctionKey):
            goToStart(nil)
        case UInt32(NSEndFunctionKey):
            goToEnd(nil)
        case 27: return deselectActionCommand()
        default:
            return handleEditorCharacter(Character(scalar), shift: shift)
        }
        return true
    }

    /// Compared as a lowercased STRING, not a `Character`: lowercasing is not
    /// one-to-one in every locale (a Turkish "İ" becomes two scalars), and
    /// `Character(String)` traps on anything but exactly one.
    private func handleEditorCharacter(_ character: Character, shift: Bool) -> Bool {
        switch character.lowercased() {
        case " ":
            playPause(nil)
        case "j":
            shuttle(forward: false)
        case "k":
            playback.pause()
        case "l":
            shuttle(forward: true)
        case "i":
            setInPoint(nil)
        case "o":
            setOutPoint(nil)
        case "n":
            toggleSnapping(nil)
        case "m":
            addMarker(nil)
        case "w":
            trimStartToPlayhead(nil)
        case "e":
            trimEndToPlayhead(nil)
        case "t":
            addTextClip(nil)
        case "c":
            toggleCropMode(nil)
        case "z" where shift:
            fitTimeline(nil)
        // Bare Z arms the canvas region mode (road map 2's phase 3b, spec §9),
        // and it must stay BELOW the ⇧Z case: a `switch` matches in source
        // order, so a bare "z" above it would swallow Fit Timeline silently.
        // The command itself toggles, so Z is also the way back out
        // (EditorViewController+ZoomRegion.swift).
        case "z":
            zoomToRegion(nil)
        // ⇧ is still applied to `charactersIgnoringModifiers`, so ⇧, arrives
        // as "<" on a US layout — both spellings mean the same nudge.
        case ",", "<":
            nudgeSelection(frames: shift ? -10 : -1)
        case ".", ">":
            nudgeSelection(frames: shift ? 10 : 1)
        default:
            return false
        }
        return true
    }

    private func stepFrames(_ count: Int) {
        guard let document = document else { return }
        playback.stepFrames(count, fps: document.editedProject.snapshot.canvas.fps)
        document.playhead = playback.currentTime
        refreshTimecode()
    }

    // MARK: - Clip, track and marker actions
    //
    // One-line forwards into `EditorViewController+Timeline.swift`, which owns
    // the bodies (app/CLAUDE.md: this file stays wiring).

    @objc func splitAtPlayhead(_ sender: Any?) { splitAtPlayheadCommand() }
    @objc func trimStartToPlayhead(_ sender: Any?) { trimToPlayhead(.start) }
    @objc func trimEndToPlayhead(_ sender: Any?) { trimToPlayhead(.end) }
    @objc func deleteClips(_ sender: Any?) { deleteSelection() }
    @objc func rippleDeleteClips(_ sender: Any?) { rippleDeleteSelection() }
    @objc func duplicateClips(_ sender: Any?) { duplicateSelection() }
    /// FillerSheetController.swift, Remove Silences' rule.
    @objc func removeFillerWords(_ sender: Any?) { removeFillerWordsCommand() }
    /// File ▸ Generate Captions… — the body and its validator are at the foot
    /// of TranscribeSheetController+Commit.swift, and File ▸ Export Captions…' are at
    /// the foot of CaptionExporter.swift: the same rule as Import Captions'
    /// and Remove Silences', a command living beside the feature it opens.
    @objc func generateCaptions(_ sender: Any?) { generateCaptionsCommand() }
    @objc func exportCaptions(_ sender: Any?) { exportCaptionsCommand() }
}

// MARK: - Timecode field

extension EditorViewController: NSTextFieldDelegate {
    /// Click-to-type on the timecode (spec §4.1). Parsing is the core's, so
    /// `1:23`, `83.5` and `1:23:04` all mean here what they mean everywhere
    /// else; anything it refuses beeps and the field snaps back.
    func controlTextDidEndEditing(_ obj: Notification) {
        guard let field = obj.object as? NSTextField, field === timecodeField,
              let document = document
        else { return }
        guard let ticks = ReelTime.parse(
            field.stringValue, fps: document.editedProject.snapshot.canvas.fps)
        else {
            NSSound.beep()
            refreshTimecode()
            return
        }
        playback.pause()
        setPlayhead(ticks)
        view.window?.makeFirstResponder(view)
    }
}

// MARK: - Split view

extension EditorViewController: NSSplitViewDelegate {
    func splitView(
        _ splitView: NSSplitView, constrainMinCoordinate proposedMinimumPosition: CGFloat,
        ofSubviewAt dividerIndex: Int
    ) -> CGFloat {
        if splitView === upperSplit {

func item(
    _ title: String,
    _ action: Selector?,
    _ key: String = "",
    _ modifiers: NSEvent.ModifierFlags = [.command]
) -> NSMenuItem {
    let item = NSMenuItem(title: title, action: action, keyEquivalent: key)
    if !key.isEmpty {
        item.keyEquivalentModifierMask = modifiers
    }
    return item
}

/// A tagged item — the idiom for a menu built from an enum's cases, so
/// the menu and the enum can never drift apart.
func tagged(_ title: String, _ action: Selector?, _ tag: Int) -> NSMenuItem {
    let item = NSMenuItem(title: title, action: action, keyEquivalent: "")
    item.tag = tag
    return item
}
}

private func appMenu() -> NSMenu {
    let menu = NSMenu(title: "Frame Job")
    menu.addItem(item("About Frame Job", #selector(AppDelegate.showAboutPanel(_:))))
    #if FRAMEJOB_UPDATER
    // Sparkle, in the published build only (spec §11 PUB-7);
    // AppDelegate+Updates.swift implements it.
    menu.addItem(item("Check for Updates…", #selector(AppDelegate.checkForUpdates(_:))))
    #endif
    menu.addItem(.separator())
    // Road map 6 §5d: the app's first window for something PERSISTED,
    // in the place macOS puts one. ⌘, is unclaimed by spec §9's table —
    // the nudge pair is the BARE `,` and `.`.
    menu.addItem(item("Settings…", #selector(AppDelegate.showSettings(_:)), ","))
    menu.addItem(.separator())
    menu.addItem(item("Hide Frame Job", #selector(NSApplication.hide(_:)), "h"))
    menu.addItem(
        item(
            "Hide Others", #selector(NSApplication.hideOtherApplications(_:)), "h",
            [.command, .option]))
    menu.addItem(item("Show All", #selector(NSApplication.unhideAllApplications(_:))))
    menu.addItem(.separator())
    menu.addItem(item("Quit Frame Job", #selector(NSApplication.terminate(_:)), "q"))
    return menu
}

private func fileMenu() -> NSMenu {
    let menu = NSMenu(title: "File")
    menu.addItem(item("New Project", #selector(newProject(_:)), "n"))
    // Directly under New Project with no separator, because both make a
    // document out of nothing (road map 3 §4). ⌥⌘N: ⌘N and ⇧⌘N are
    // taken, and the modifier keeps the key off the first responder. It
    // reads "Stop Recording" while one runs — `AppDelegate.validateMenuItem`
    // retitles it, the agent-server item's precedent.
    menu.addItem(
        item(
            "New Recording…", #selector(AppDelegate.newRecording(_:)), "n",
            [.command, .option]))
    // Retitled Resume Recording and enabled only while a recording runs
    // (`validateMenuItem`); no key (#98).
    menu.addItem(item("Pause Recording", #selector(AppDelegate.pauseOrResumeRecording(_:))))
    // The In–Out range as a new untitled project (spec §11 CJ-52); no key.
    menu.addItem(
        item(
            "New Project from Range…",
            #selector(EditorViewController.newProjectFromRange(_:))))
    // The timeline's 9:16, 4:5 or 1:1 version, opened as a copy or made in place (spec §11
    // VR-39); no key.
    menu.addItem(
        item(
            "Make Vertical Version…",
            #selector(EditorViewController.showVerticalVersionSheet(_:))))
    menu.addItem(item("Open…", #selector(NSDocumentController.openDocument(_:)), "o"))

    // AppKit auto-populates a submenu whose sole item's action is
    // clearRecentDocuments: as the Open Recent menu.
    let openRecent = NSMenu(title: "Open Recent")
    openRecent.addItem(
        item("Clear Menu", #selector(NSDocumentController.clearRecentDocuments(_:))))
    let openRecentItem = NSMenuItem(title: "Open Recent", action: nil, keyEquivalent: "")
    openRecentItem.submenu = openRecent
    menu.addItem(openRecentItem)

    menu.addItem(.separator())
    menu.addItem(item("Close", #selector(NSWindow.performClose(_:)), "w"))
    menu.addItem(item("Save", #selector(NSDocument.save(_:)), "s"))
    menu.addItem(item("Save As…", #selector(NSDocument.saveAs(_:)), "s", [.command, .shift]))
    menu.addItem(item("Revert to Saved", #selector(NSDocument.revertToSaved(_:))))
    menu.addItem(.separator())
    menu.addItem(
        item(
            "Add Media…", #selector(EditorViewController.addMediaFiles(_:)), "i",
            [.command, .shift]))
    // The three caption items sit together, in the order a caption track
    // comes into being and leaves again: read one in, make one from
    // speech, write one back out. None of the three takes a key
    // equivalent — spec §9's "proposed, not yet bound" table claims no
    // row for phase 4, and a modifier-less menu key would be resolved
    // ahead of the first responder and steal a letter the editor's own
    // `keyDown` owns (the reason recorded at Remove Silences… below).
    menu.addItem(
        item("Import Captions…", #selector(EditorViewController.importCaptions(_:))))
    menu.addItem(
        item("Generate Captions…", #selector(EditorViewController.generateCaptions(_:))))
    menu.addItem(
        item("Export Captions…", #selector(EditorViewController.exportCaptions(_:))))
    // Road map creator-jobs VR4a (spec §11 VR-45): the word caption tracks re-paged on the
    // canvas being edited, one undo step; no key, the caption items' reason above.
    menu.addItem(
        item(
            "Re-lay Captions for This Canvas",
            #selector(EditorViewController.relayCaptions(_:))))
    menu.addItem(
        item("Consolidate Media…", #selector(EditorViewController.consolidateMedia(_:))))
    // Road map 10's G5b: a face or a picture into the package's
    // graphics/, `import_graphic_font`'s and `import_graphic_asset`'s
    // body. No key equivalents, the caption items' reason above.
    menu.addItem(
        item("Add Font to Graphics…", #selector(EditorViewController.addGraphicFont(_:))))
    menu.addItem(
        item("Add Image to Graphics…", #selector(EditorViewController.addGraphicImage(_:))))
    addGraphicFileItems(to: menu)
    menu.addItem(.separator())
    menu.addItem(item("Export…", #selector(EditorViewController.exportProject(_:)), "e"))
    // Save Frame… is the still-image sibling of Export… and sits beside
    // it under the same letter (road map 2's phase 7a): ⌘E writes the
    // movie, ⌥⌘E writes the one frame under the playhead. Spec §9's
    // "proposed, not yet bound" table claimed ⌥⌘E for this phase and the
    // row has been promoted into the bound table above it. The modifier
    // matters: a modifier-less menu key equivalent is resolved ahead of
    // the first responder, which is why the caption items take none, but
    // ⌥⌘ is nobody's bare key.
    menu.addItem(
        item(
            "Save Frame…", #selector(EditorViewController.saveFrame(_:)), "e",
            [.command, .option]))
    return menu
}

private func editMenu() -> NSMenu {
    let menu = NSMenu(title: "Edit")
    // NSUndoManager answers these through the responder chain; the
    // document owns the manager, so there is nothing to implement here.
    menu.addItem(item("Undo", Selector(("undo:")), "z"))
    menu.addItem(item("Redo", Selector(("redo:")), "z", [.command, .shift]))
    menu.addItem(.separator())
    menu.addItem(item("Cut", #selector(EditorViewController.cut(_:)), "x"))
    menu.addItem(item("Copy", #selector(EditorViewController.copy(_:)), "c"))
    menu.addItem(item("Paste", #selector(EditorViewController.paste(_:)), "v"))
    menu.addItem(
        item(
            "Paste Attributes", #selector(EditorViewController.pasteAttributes(_:)), "v",
            [.command, .option]))
    menu.addItem(
        item(
            "Paste Graphic Properties",
            #selector(EditorViewController.pasteGraphicProperties(_:))))
    menu.addItem(
        item("Duplicate", #selector(EditorViewController.duplicateClips(_:)), "d"))
    // Bare ⌫: U+0008 (NSBackspaceCharacter) is what AppKit matches the
    // Delete key against and what it draws as ⌫ (U+007F is forward
    // delete, ⌦). A modifier-less key equivalent is resolved ahead of the
    // first responder, so EditorViewController.validateUserInterfaceItem
    // must keep this item disabled unless there is something to delete
    // and no text is being edited — otherwise it swallows every Delete.
    menu.addItem(
        item("Delete", #selector(EditorViewController.deleteClips(_:)), "\u{8}", []))
    menu.addItem(
        item(
            "Ripple Delete", #selector(EditorViewController.rippleDeleteClips(_:)),
            "\u{8}", [.command]))
    menu.addItem(.separator())
    // The two placement edits for the Media tab's selected file. No key
    // equivalent: they are reached often enough from the row's own
    // context menu and from an ⌥ / ⇧⌥ drop, and the letters a cutter
    // expects for them (F and D) are both taken.
    menu.addItem(
        item(
            "Insert at Playhead", #selector(EditorViewController.insertMediaAtPlayhead(_:))))
    menu.addItem(
        item(
            "Overwrite at Playhead",
            #selector(EditorViewController.overwriteMediaAtPlayhead(_:))))
    menu.addItem(.separator())
    menu.addItem(item("Select All", #selector(EditorViewController.selectAll(_:)), "a"))
    menu.addItem(
        item(
            "Select After Playhead", #selector(EditorViewController.selectAfterPlayhead(_:)),
            "a", [.command, .option]))
    menu.addItem(
        item(
            "Select All on Track", #selector(EditorViewController.selectAllClipsOnTrack(_:))))
    return menu
}

    private func clipMenu() -> NSMenu {
        let menu = NSMenu(title: "Clip")
        menu.addItem(item("Split", #selector(EditorViewController.splitAtPlayhead(_:)), "t"))
        // Road map "creator-jobs" CJ2b (spec §11 CJ-29), beside Split: the UI
        // path `split_at_shots` names. No key equivalent, for Normalize's reason.
        menu.addItem(
            item("Split at Shot Changes", #selector(EditorViewController.splitAtShotChanges(_:))))
        // W and E are BARE keys (spec §9), handled in the editor's keyDown so
        // they can never be stolen from a text field the way a modifier-less
        // key equivalent would be.
        menu.addItem(
            item("Trim Start to Playhead", #selector(EditorViewController.trimStartToPlayhead(_:))))
        menu.addItem(
            item("Trim End to Playhead", #selector(EditorViewController.trimEndToPlayhead(_:))))
        menu.addItem(.separator())
        menu.addItem(
            item(
                "Freeze Frame", #selector(EditorViewController.freezeFrame(_:)), "f",
                [.command, .shift]))
        menu.addItem(
            item(
                "Detach Audio", #selector(EditorViewController.detachAudio(_:)), "d",
                [.command, .option]))
        // Detach Audio's way back (spec §11 AU-95, AU-97): its key plus ⇧.
        menu.addItem(
            item(
                "Attach Audio", #selector(EditorViewController.attachAudio(_:)), "d",
                [.command, .option, .shift]))
        // Road map 2's phase 5c, next to Detach Audio because those two are
        // the Clip menu's only sound commands. It duplicates the Audio
        // section's button deliberately (contract D-C8): a command reachable
        // from a pane alone can be lost — Add Shape's lesson — and a menu item
        // is what gives the `normalize_clip` mirror a UI path to name.
        //
        // No key equivalent: spec §9's "proposed, not yet bound" table claims
        // no row for phase 5, and a modifier-less menu key would be resolved
        // ahead of the first responder and steal a letter the editor's own
        // `keyDown` owns (the reason spelled out at Remove Silences… below).
        //
        // The title is the button's title and the string `AgentCatalog`'s
        // `normalize_clip` description names as this command's UI path. Three
        // spellings of one command is how the halves drift.
        menu.addItem(.separator())
